def index_sections(lines):
    result = build_outline(lines)
    if isinstance(result, dict) and "error" in result:
        return result
    outline = result
    entries = []
    def traverse(node, path):
        if node["level"] > 3:
            return
        current_path = path + [str(len(path) + 1)]
        entries.append({"number": ".".join(current_path), "title": node["title"]})
        for child in node["children"]:
            traverse(child, current_path)
    for node in outline:
        traverse(node, [])
    return entries

